from ratefeed import RateCache

def test_ratecache_init_defaults():
    cache = RateCache()
    assert cache.ttl.total_seconds() == 300
    assert cache._entries == {}
    assert cache.misses == 0
    assert cache._fetch.__name__ == "fetch_rates"
    assert cache._clock.__name__ == "now"

def test_ratecache_init_custom():
    def dummy_fetch():
        return {}
    def dummy_clock():
        return None
    cache = RateCache(ttl_seconds=600, fetch=dummy_fetch, clock=dummy_clock)
    assert cache.ttl.total_seconds() == 600
    assert cache._fetch is dummy_fetch
    assert cache._clock is dummy_clock
    assert cache._entries == {}
    assert cache.misses == 0

import ratefeed

def test_invalidate_covers_both_branches():
    # Locate the class that provides the invalidate method
    InvalidateClass = None
    for name in dir(ratefeed):
        obj = getattr(ratefeed, name)
        if isinstance(obj, type) and hasattr(obj, 'invalidate'):
            InvalidateClass = obj
            break
    assert InvalidateClass is not None, "Could not find a class with an invalidate method"
    # Try to instantiate; if it requires arguments, we fall back to manual setup
    try:
        cache = InvalidateClass()
    except Exception:
        cache = InvalidateClass.__new__(InvalidateClass)
        # Ensure the instance has the _entries attribute
        if not hasattr(cache, '_entries'):
            cache._entries = {}
    # Test branch where base is None -> clear all entries
    cache._entries = {'foo': 1, 'bar': 2}
    cache.invalidate(base=None)
    assert cache._entries == {}, "Entries should be cleared when base is None"
    # Test branch where base is given -> remove specific entry
    cache._entries = {'apple': 5, 'banana': 3}
    cache.invalidate(base='apple')
    assert cache._entries == {'banana': 3}, "Only the specified base should be removed"
    # Removing a non‑existent base should leave the dict unchanged
    cache.invalidate(base='nonexistent')
    assert cache._entries == {'banana': 3}, "Dict should stay the same when base not present"

