from logscan import grep

def test_grep_matches_records():
    records = [
        {"message": "hello world"},
        {"message": "HELLO WORLD"},
        {"message": "goodbye"}
    ]
    # case-sensitive search
    assert grep(records, r"hello") == [{"message": "hello world"}]
    # case-insensitive search
    assert grep(records, r"hello", ignore_case=True) == [
        {"message": "hello world"},
        {"message": "HELLO WORLD"}
    ]
    # regex anchor
    assert grep(records, r"world$") == [{"message": "hello world"}]

