    def fake_fetch(base):
        called["base"] = base
        return {"EUR": 0.9}

    feed = RateFeed(fetch=fake_fetch, ttl=300)

    # Act
    rates = feed.get("USD")

    # Assert
    assert rates == {"EUR": 0.9}
    assert called["base"] == "USD"
